// The renderer owns the final overlap-adjusted display position.
if (window.StaffRendering) { window.StaffRendering.refresh(marker); return; }
window.StaffPopup.setPosition(marker, lat, lon);

const previousPosition = marker.getLatLng();
if (previousPosition.lat !== lat || previousPosition.lng !== lon) {
  marker.setLatLng([lat, lon]);
}
const previousIcon = marker.options.icon?.options;
const nextIcon = icon.options;
if (!previousIcon || previousIcon.html !== nextIcon.html ||
    JSON.stringify([previousIcon.iconSize, previousIcon.iconAnchor, previousIcon.className]) !==
    JSON.stringify([nextIcon.iconSize, nextIcon.iconAnchor, nextIcon.className])) {
  marker.setIcon(icon);
}

map.scrollWheelZoom.enable();

// Temporary local camera diagnostics. No listeners or wrappers until start().
window.BTRMapInteractionDiagnostics = (function(map){
  let enabled=false; const records=[], originals=new Map();
  const events='dragstart dragend click dblclick boxzoomstart boxzoomend movestart moveend zoomstart zoomend';
  function record(type,e,stack){
    if(!enabled)return;
    const event=e?.originalEvent||e,center=map.getCenter();
    if(records.length===500)records.shift();
    records.push({at:performance.now(),type,zoom:map.getZoom(),center:{lat:center.lat,lng:center.lng},
      detail:event?.detail,button:event?.button,shiftKey:event?.shiftKey,deltaY:event?.deltaY,
      pointerType:event?.pointerType,target:event?.target?.tagName,stack});
  }
  const onMap=e=>record(e.type,e),onWheel=e=>record('wheel',e);
  function stop(){
    if(!enabled)return;enabled=false;map.off(events,onMap);
    map.getContainer().removeEventListener('wheel',onWheel,true);
    for(const [name,pair]of originals)if(map[name]===pair.wrapper)map[name]=pair.original;
    originals.clear();
  }
  return {start(){if(enabled)return;enabled=true;records.length=0;map.on(events,onMap);
    map.getContainer().addEventListener('wheel',onWheel,{capture:true,passive:true});
    for(const name of ['setView','setZoom','setZoomAround','fitBounds','flyTo','flyToBounds','panTo','panBy','panInside','zoomIn','zoomOut']){
      const original=map[name];if(typeof original!=='function')continue;
      const wrapper=function(...args){record('camera:'+name,null,new Error().stack);return original.apply(this,args);};
      originals.set(name,{original,wrapper});map[name]=wrapper;
    }record('started');
  },stop,report(){return records.map(row=>({...row,center:{...row.center}}));},clear(){records.length=0;}};
})(map);

css/tigerTeams.css.before:
.btr-tiger-team-icon .btr-team-monitoring::before {
  content:"";
  position:absolute;
  width:19px;
  height:19px;
  box-sizing:border-box;
  left:50%;
  top:50%;
  border:1px solid var(--btr-team-color);
  border-radius:50%;
  pointer-events:none;
  animation:btr-team-monitoring-pulse 3s ease-out infinite;
}
@keyframes btr-team-monitoring-pulse {
  0% { transform:translate(-50%,-50%) scale(1); opacity:.45; }
  75%,100% { transform:translate(-50%,-50%) scale(1.25); opacity:0; }
}
@media (prefers-reduced-motion:reduce) {
  .btr-tiger-team-icon .btr-team-monitoring::before { animation:none; opacity:0; }
}
